import {teamAccessView,teamAccessAction,teamAccessForm} from './team-access.mjs';
import {offerQueue,taxonomyAdmin,offerAdminAction,offerAdminForm} from './offer-admin.mjs';
import {offersView,offerAction,offerForm} from './offer-editor.mjs';
import {CITY_NAMES} from '/cities.mjs';
import {esc,icon,link,btn,money,time,date,field,textarea,select,badge,status,hhmm,minute,photo,empty,crumbs,errorHTML,searchHash,userError} from './ui.mjs';
import {serviceCard} from './public-views.mjs';
import {guides} from './content.mjs';
import {accountEntry} from './account-ui.mjs';
import {conversations} from './chat-ui.mjs';
import {serviceEditorDialog,serviceEditorValues} from './service-editor.mjs';
import {calendarView,calendarAction,calendarForm} from './calendar-ui.mjs';
const navs={customer:[['vizitai','Vizitai'],['issaugoti','Išsaugoti'],['pranesimai','Pranešimai'],['profilis','Profilis'],['nustatymai','Nustatymai']],professional:[['','Apžvalga'],['kalendorius','Kalendorius'],['uzklausos','Užklausos'],['laukiantieji','Laukiantieji'],['klientai','Klientai'],['paslaugos','Paslaugos'],['grafikas','Grafikas'],['resursai','Resursai'],['komanda','Komanda'],['prieigos','Komandos prieigos'],['profilis','Profilis'],['galerija','Galerija'],['pranesimai','Pranešimai'],['ataskaitos','Ataskaitos'],['integracijos','Integracijos'],['nustatymai','Nustatymai']],operator:[['','Patvirtinimai'],['katalogas','Katalogas'],['skundai','Skundai'],['pristatymas','Pristatymas'],['turinys','Turinys'],['rodikliai','Rodikliai']]};
const navCapability={kalendorius:'bookings',uzklausos:'clients',laukiantieji:'clients',klientai:'clients',paslaugos:'offers',grafikas:'schedule',resursai:'resources',komanda:'team',prieigos:'access',profilis:'profile',galerija:'profile',pranesimai:'messages',ataskaitos:'reports',integracijos:'access',pradzia:'profile',nustatymai:'schedule'};
const allowed=(ctx,slug)=>ctx.adapter.mode!=='real'||!navCapability[slug]||ctx.workspace?.capabilities?.includes(navCapability[slug]);
const bases={customer:'/paskyra',professional:'/meistrui',operator:'/operatorius'};
export function manualServiceSummary(ctx,id){
 const s=ctx.workspace.services.find(s=>s.id===id);if(!s)return '';
 const staff=ctx.workspace.practitioners.find(p=>p.id===s.practitionerId);
 return `<strong>${esc(s.label)}</strong><p>${esc(staff?.name||'Meistras')}<br>${s.durationMin} min. · ${money(s.priceMinor)}</p>`;
}
export async function entryView(ctx,target=null){
  if(ctx.adapter.mode==='real')return accountEntry(ctx,target||ctx.state.afterAuth||'/paskyra');
  const ids=await ctx.adapter.demoIdentities();ctx.identities=ids;return`<div class="page container"><h1 class="page-title">Tavo paskyra</h1><div class="account-options"><article class="panel"><h2>Tavo vizitai</h2><p>Registracijos, pokalbiai ir išsaugoti meistrai.</p>${btn('sandbox-entry','Atidaryti vizitus','data-role="customer"','button accent')}</article><article class="panel"><h2>Tavo darbo vieta</h2><p>Paslaugos, grafikas ir klientai vienoje vietoje.</p>${btn('sandbox-entry','Atidaryti darbo vietą','data-role="professional"','button accent')}</article></div></div>`;

}
function shell(ctx,title,content,role){const base=bases[role];return`<div class="page container"><div class="workspace"><aside class="sidebar"><p class="status-line">${{customer:'Kliento paskyra',professional:'Meistro darbo vieta',operator:'Operatoriaus darbo vieta'}[role]}</p>${role==='professional'?(ctx.identities.organizations.length>1?`<form id="switch-organization">${select('Darbo vieta','organizationId',ctx.identities.organizations.map(o=>[o.id,o.name]),ctx.state.session.organizationId)}<button class="button outline small">Keisti</button></form>`:`<p class="workspace-name">${esc(ctx.identities.organizations[0]?.name||'Tavo darbo vieta')}</p>`):''}<nav aria-label="Darbo vietos navigacija">${navs[role].filter(([slug])=>role!=='professional'||allowed(ctx,slug)).map(([slug,l])=>link(base+(slug?'/'+slug:''),l,(ctx.path===base+(slug?'/'+slug:'')||slug&&ctx.path.startsWith(base+'/'+slug+'/'))?'active':'')).join('')}</nav><div class="divider"></div>${link('/paskyra','Mano paskyra','link')}</aside><div class="workspace-content"><h1>${title}</h1>${content}</div></div></div>`;}
const list=(rows,render,copy='Šiame pasirinkime įrašų nėra.',action='')=>rows.length?rows.map(render).join(''):empty('Įrašų dar nėra',copy,action);
function requestHistory(d){
 const rows=[...(d.inquiries||[]).map(i=>({...i,kind:'Užklausa',requestState:i.status})),...(d.waitlist||[]).map(i=>({...i,kind:'Laukiančiųjų sąrašas',requestState:i.state}))].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
 return `<p>Čia rasi savo pateiktas užklausas ir pageidavimus. Laikas dar nepatvirtintas; pasiūlymas laukiančiųjų sąraše nėra rezervacija.</p>${list(rows,i=>`<article class="list-row" data-request-id="${esc(i.id)}"><div><strong>${esc(i.serviceLabel||'Paslauga')}</strong><p>${esc(i.organizationName||'Paslaugos teikėjas')} · ${esc(i.kind)}<br>Pateikta ${date(i.createdAt)} · ${time(i.createdAt)}</p><p>${esc(i.note)}</p>${badge(i.requestState)}<p class="hint">Laikas nepatvirtintas.</p></div></article>`,'Pateik pageidavimą pasirinktos paslaugos laiko paieškoje.',link('/paieska','Rasti paslaugą','button outline'))}`;
}
function visitLine(ctx,b,customer=false,detail=false){const s=ctx.rows.find(s=>s.id===b.providerServiceId);return`<div class="list-row"><div><strong>${esc(b.serviceSnapshot?.label||s?.label||'Paslauga')}</strong>${!customer?`<p class="visit-client">${esc(ctx.workspace?.clients?.find(c=>c.id===b.clientId)?.name||'Klientas')}</p>`:''}<p>${date(b.startAt)} · ${time(b.startAt)}–${time(b.endAt)} · ${money(b.priceMinor)}<br>${esc(b.serviceSnapshot?.practitionerName||ctx.workspace?.practitioners?.find(p=>p.id===b.practitionerId)?.name||s?.practitionerName||'Paslaugos teikėjas')}</p>${badge(b.status)}</div>${detail?'':customer?link('/paskyra/vizitai/'+b.id,'Detalės','button outline small'):btn('visit-drawer','Atidaryti',`data-id="${b.id}"`,'button outline small')}</div>`;}
export async function workspaceView(ctx,path){
  if(path==='/paskyra')return entryView(ctx);
  const role=path.startsWith('/meistrui')?'professional':path.startsWith('/operatorius')?'operator':'customer';
  if(ctx.adapter.mode==='real'){const entry=await accountEntry(ctx,path);if(entry)return entry;}
  if(ctx.state.session.role!==role)return entryView(ctx,path);
  const data=await ctx.adapter.workspace(ctx.state.session);ctx.workspace=data;for(const a of data.media||[])ctx.media.set(a.id,{id:a.id,alt:a.alt,variants:a.variants.map(v=>({...v,file:v.file||'api/madbeauty/media/'+v.storageFile}))});ctx.rows=role==='customer'?await ctx.adapter.catalog():role==='professional'?data.services.map(s=>({...s,practitionerName:data.practitioners.find(p=>p.id===s.practitionerId)?.name})):[];ctx.identities=await ctx.adapter.demoIdentities();
  if(role==='customer')return customerView(ctx,path,data);
  if(role==='operator')return operatorView(ctx,path,data);
  return professionalView(ctx,path,data);
}
async function customerView(ctx,path,d){
  const part=path.split('/')[2],id=path.split('/')[3];let title='',content='';
  if(part==='vizitai'&&id){const b=d.bookings.find(b=>b.id===id);if(!b)return null;title='Tavo vizitas';content=visitLine(ctx,b,true,true)+`<div class="toolbar">${b.status==='confirmed'&&Date.parse(b.startAt)>Date.parse(ctx.adapter.clock.now)?btn('reschedule','Pakeisti laiką',`data-id="${b.id}"`,'button accent')+btn('cancel-visit','Atšaukti vizitą',`data-id="${b.id}"`,'button outline'):''}${b.status==='completed'?(d.reviews.some(r=>r.bookingId===b.id)?'<span class="pill">Atsiliepimas jau pateiktas</span>':btn('review-visit','Parašyti atsiliepimą',`data-id="${b.id}"`,'button outline')):''}${btn('message-visit','Pokalbis',`data-id="${b.id}"`,'button outline')}</div><p>Pasirinkta kaina ir trukmė susietos su šiuo vizitu. </p>${link('/atsaukimas','Pakeitimo principai','link')}`;}
  else if(part==='vizitai'){title='Tavo laikas';const tab=new URLSearchParams(location.hash.slice(1)).get('būsena')||'upcoming',now=Date.parse(ctx.adapter.clock.now),rows=d.bookings.filter(b=>tab==='past'?b.status==='completed'||b.status==='confirmed'&&Date.parse(b.endAt)<=now:tab==='canceled'?b.status==='canceled':b.status==='confirmed'&&Date.parse(b.endAt)>now).sort((a,b)=>tab==='upcoming'?a.startAt.localeCompare(b.startAt):b.startAt.localeCompare(a.startAt));content=`<nav class="tabs" aria-label="Vizitų ir pageidavimų būsenos">${[['upcoming','Būsimi'],['past','Buvę'],['canceled','Atšaukti'],['pageidavimai','Pageidavimai']].map(([id,l])=>link('/paskyra/vizitai#būsena='+id,l,tab===id?'active':'')).join('')}</nav>${tab==='pageidavimai'?requestHistory(d):list(rows,b=>visitLine(ctx,b,true),'Pasirink paslaugą ir tau tinkantį laiką.',link('/paieska','Rasti paslaugą','button outline'))}`;}
  else if(part==='issaugoti'){title='Tavo išsaugoti profiliai';if(ctx.adapter.mode==='real')ctx.state.favorites=d.client.favoriteIds||[];const rows=ctx.rows.filter((r,i,a)=>ctx.state.favorites.includes(r.organizationId)&&a.findIndex(s=>s.organizationId===r.organizationId)===i);content=`<div class="cards">${(await Promise.all(rows.map(r=>serviceCard(ctx,r,ctx.state.search)))).join('')||empty('Dar nėra išsaugotų profilių','Išsaugok patikusį meistrą kataloge.',link('/paieska','Naršyti paslaugas'))}</div>`;}
  else if(part==='pranesimai'){title='Pokalbiai';content=conversations(ctx,d,'customer');}
  else if(part==='profilis'){title='Tavo duomenys';content=`<form id="customer-profile" class="panel prose">${field('Vardas','name',d.client.name,'text','required maxlength="80"')}<p>Prisijungimo el. paštas: ${esc(d.client.email)}.</p><button class="button accent">Išsaugoti vardą</button></form>`;}
  else if(part==='nustatymai'){const p=d.preferences[0];title='Komunikacijos ir privatumas';content=`<form id="customer-settings" class="panel prose"><label class="check-label"><input type="checkbox" name="service" ${p?.service!==false?'checked':''}><span>Vizito pranešimai</span></label><label class="check-label"><input type="checkbox" name="marketing" ${p?.marketing?'checked':''}><span>Rinkodaros pranešimai</span></label><p class="hint">Vizito pranešimai ir rinkodara yra atskiri pasirinkimai.</p><button class="button accent">Išsaugoti pasirinkimus</button></form><div class="toolbar">${link('/privatumas','Duomenų naudojimas','link')}${btn('account-logout','Atsijungti','','button outline')}</div>`;}
  else return null;
  return shell(ctx,title,content,'customer');
}
const calendar=(ctx,d)=>calendarView(ctx,d,visitLine);
async function professionalView(ctx,path,d){
  const part=path.split('/')[2]||'',id=path.split('/')[3],org=d.organizations[0];let title='',content='';
  if(!allowed(ctx,part))return shell(ctx,'Prieiga nepriskirta',empty('Šios skilties prieiga nepriskirta','Darbo vietos savininkas gali suteikti reikalingą komandos prieigą.',link('/meistrui/kalendorius','Atidaryti savo kalendorių','button outline')),'professional');
  if(part==='prieigos'){title='Komandos prieigos';content=teamAccessView(ctx,d);}
  else if(part==='pradzia')return onboarding(ctx,d);
  else if(part===''){title='Tavo darbo diena';const today=d.bookings.filter(b=>date(b.startAt)===ctx.dayLabel(0)&&b.status==='confirmed');content=`<p>${esc(org.name)} · ${ctx.dayLabel(0)}</p>${!org.approved&&allowed(ctx,'profilis')?`<div class="alert"><div><strong>${org.profileState==='pending'?'Profilis laukia peržiūros':'Profilis dar nepublikuotas'}</strong><p>${org.profileState==='pending'?'Darbo vietą gali naudoti; kataloge profilis pasirodys priėmus versiją.':'Parenk paslaugas, darbo grafiką ir pateik profilį peržiūrai.'}</p>${link('/meistrui/profilis','Peržiūrėti profilio būseną','link')}</div></div>`:''}<div class="stats"><div><strong>${today.length}</strong><span>Šios dienos vizitai</span></div><div><strong>${d.inquiries.filter(i=>i.status==='new').length}</strong><span>Naujos užklausos</span></div><div><strong>${d.waitlist.filter(i=>i.state==='waiting').length}</strong><span>Laukia laiko</span></div></div>${link('/meistrui/kalendorius','Atidaryti kalendorių')}<h2 style="font-size:26px;margin-top:32px">Dienos vizitai</h2>${list(today,b=>visitLine(ctx,b),'Šiandien vizitų nėra. Naują registraciją gali pridėti kalendoriuje.',link('/meistrui/kalendorius','Planuoti vizitą','button outline'))}<div class="toolbar">${allowed(ctx,'pradzia')?link('/meistrui/pradzia','Užbaigti profilio parengimą','link'):''}${allowed(ctx,'uzklausos')?link('/meistrui/uzklausos','Peržiūrėti užklausas','link'):''}</div>`;}
  else if(part==='kalendorius'){title='Kalendorius';content=calendar(ctx,d);}
  else if(part==='uzklausos'){title='Užklausos';content=`<p>Čia rasi klientų pageidavimus. Aptaręs paslaugą ir laiką, pakeisk užklausos būseną.</p>${list(d.inquiries,i=>`<div class="list-row"><div><strong>${esc(d.clients.find(c=>c.id===i.clientId)?.name||'Klientas')}</strong>${d.clients.find(c=>c.id===i.clientId)?.email?'<p>'+esc(d.clients.find(c=>c.id===i.clientId).email)+'</p>':''}<p>${esc(d.services.find(s=>s.id===i.providerServiceId)?.label||'Paslauga')}</p><p>${esc(i.note||'Pageidauja aptarti procedūrą ir laiką.')}</p>${badge(i.status)} ${badge(i.deliveryStatus)}</div>${btn('inquiry-status','Keisti būseną',`data-id="${i.id}"`,'button outline small')}</div>`)}`;}
  else if(part==='laukiantieji'){title='Laukiančiųjų sąrašas';content=`<p>Pasiūlymas nėra rezervacija. Klientas turės pats peržiūrėti ir patvirtinti naują laiką.</p>${list(d.waitlist,w=>`<div class="list-row"><div><strong>${esc(d.clients.find(c=>c.id===w.clientId)?.name||'Klientas')}</strong>${d.clients.find(c=>c.id===w.clientId)?.email?'<p>'+esc(d.clients.find(c=>c.id===w.clientId).email)+'</p>':''}<p>${esc(d.services.find(s=>s.id===w.providerServiceId)?.label||'Paslauga')}</p><p>${esc(w.note||'Pageidauja artimiausio tinkamo laiko.')}</p>${badge(w.state)}</div>${btn('waitlist-status','Peržiūrėti pasiūlymą',`data-id="${w.id}"`,'button outline small')}</div>`)}`;}
  else if(part==='klientai'&&id){const c=d.clients.find(c=>c.id===id);if(!c)return null;title=c.name;content=`<p>${esc(c.email)}</p><h2 style="font-size:26px">Vizitų istorija</h2>${list(d.bookings.filter(b=>b.clientId===id),b=>visitLine(ctx,b))}`;}
  else if(part==='klientai'){title='Tavo klientai';content=`${ctx.adapter.mode==='real'?btn('new-client','Pridėti klientą','','button accent'):''}<p>Rodomi tik pasirinktos organizacijos klientai. </p><form id="client-filter" class="row"><input class="input" name="term" aria-label="Ieškoti kliento" placeholder="Vardas" value="${esc(ctx.state.clientFilter||'')}"><button class="button outline">Ieškoti</button></form>${list(d.clients.filter(c=>!ctx.state.clientFilter||c.name.toLocaleLowerCase('lt').includes(ctx.state.clientFilter.toLocaleLowerCase('lt'))),c=>`<div class="list-row"><div><strong>${esc(c.name)}</strong><p>${esc(c.email)}</p></div>${link('/meistrui/klientai/'+c.id,'Kortelė','button outline small')}</div>`)}`;}
  else if(part==='paslaugos'&&ctx.adapter.mode==='real'){title='Tavo pasiūlymai ir variantai';content=offersView(ctx,d);}
  else if(part==='paslaugos'){title='Tavo paslaugos';content=`<div class="toolbar"><p>Varianto kaina ir trukmė naudojama profilyje, laikuose ir vizito santraukoje.</p>${ctx.adapter.mode==='real'?btn('new-service','Pridėti paslaugą','','button accent'):''}</div>${list(d.services,s=>`<div class="service-line"><div><h3>${esc(s.label)}</h3><p>${s.durationMin} min. · ${money(s.priceMinor)} · ${esc(d.practitioners.find(p=>p.id===s.practitionerId)?.name)}<br>Priedai: ${s.addons.map(a=>esc(a.label)+' +'+a.durationMin+' min.').join(', ')}</p></div>${btn('edit-service','Redaguoti',`data-id="${s.id}"`,'button outline small')}</div>`)}`;}
  else if(part==='grafikas'){title='Pamainos ir pertraukos';content=`<p>Viešos darbo valandos nėra darbuotojo pamaina. Pakeitimas negali paslėpti esamo vizito.</p>${d.schedules.map(s=>`<div class="list-row"><div><strong>${esc(d.practitioners.find(p=>p.id===s.practitionerId)?.name)}</strong><p>${hhmm(s.startMin)}–${hhmm(s.endMin)} · pertrauka ${hhmm(s.breakStartMin)}–${hhmm(s.breakEndMin)}${s.closedDate?'<br>Uždarymas: '+esc(s.closedDate):s.closedDay!=null?'<br>Uždarymas: '+ctx.dayLabel(s.closedDay):''}</p></div>${btn('edit-schedule','Keisti pamainą',`data-id="${s.id}"`,'button outline small')}</div>`).join('')}`;}
  else if(part==='resursai'){title='Kabinetai ir įranga';content=`${ctx.adapter.mode==='real'?btn('new-resource','Pridėti darbo vietą','','button accent'):''}<p>Vienas procedūros resursas negali būti skiriamas dviem persidengiantiems vizitams.</p>${d.resources.map(r=>`<div class="list-row"><div><strong>${esc(r.label)}</strong><p>${r.active?'Prieinamas laiko paieškoje':'Išjungtas laiko paieškoje'}</p></div>${btn('edit-resource','Redaguoti',`data-id="${r.id}"`,'button outline small')}</div>`).join('')}`;}
  else if(part==='komanda'){title='Tavo komanda';content=`${ctx.adapter.mode==='real'?btn('new-staff','Pridėti komandos narį','','button accent'):''}<p>${org.kind==='solo'?'Tai savarankiškai dirbančio meistro paskyra.':'Komandos rolės ir paslaugų kompetencijos yra atskiros.'}</p>${d.practitioners.map(p=>`<div class="list-row"><div class="row"><span class="avatar">${esc(p.initials)}</span><div><strong>${esc(p.name)}</strong><p>${esc(p.role||'Meistras')} · ${d.services.filter(s=>s.practitionerId===p.id).map(s=>esc(s.label)).join(', ')}</p></div></div>${btn('edit-team','Rolė ir vardas',`data-id="${p.id}"`,'button outline small')}</div>`).join('')}<p class="hint">Kompetencija konkrečiam variantui keičiama paslaugos redaktoriuje. Komandos prieigos administruojamos atskirai.</p>`;}
  else if(part==='profilis'){title='Tavo viešas profilis';content=`<form id="profile-revision" class="panel prose">${field('Pavadinimas','name',org.name,'text','required maxlength="100"')}${textarea('Aprašymas','bio',org.bio,'required maxlength="600"')}<button class="button accent">Pateikti versiją peržiūrai</button></form><h2 style="font-size:26px;margin-top:32px">Versijų istorija</h2>${list(d.revisions,r=>`<div class="list-row"><div><strong>${esc(r.name)}</strong><p>${esc(r.reason||'Profilio peržiūra')}</p>${badge(r.state)}</div></div>`,'Pateik pirmą šio profilio versiją.')}<div class="toolbar">${link('/'+(org.kind==='salon'?'salonai':'meistrai')+'/'+org.id,'Peržiūrėti profilį','link')}${link('/meistrui/pradzia','Pilna pradžios eiga','link')}</div>`;}
  else if(part==='galerija'&&ctx.adapter.mode==='real'){title='Tavo vaizdai';const ids=[org.draftAvatarImageId||org.avatarImageId,...(org.draftGallery||org.gallery)].filter(Boolean);content=`<p>Įkelk portretą ir savo darbų arba aplinkos vaizdus. Nauji vaizdai pasirodys viešame profilyje priėmus jo versiją.</p><div class="gallery-grid">${ids.map(id=>photo(ctx,id)).join('')}</div><form id="profile-upload" class="panel prose" style="margin-top:28px"><label for="profile-file">PNG, JPEG arba WebP · iki 12 MB</label><input id="profile-file" class="input" name="file" type="file" accept="image/png,image/jpeg,image/webp" required>${select('Vaizdo paskirtis','usage',[['gallery','Darbas arba aplinka'],['portrait','Profilio portretas']],'gallery')}${field('Vaizdo aprašas','alt','','text','required maxlength="250"')}${textarea('Kilmė ir viešinimo teisė','rights','','required maxlength="600"')}<label class="check-label"><input type="checkbox" name="rightsAccepted" required>Turiu teisę viešinti šį vaizdą ir jame esančių žmonių atvaizdą.</label><button class="button accent">Įkelti vaizdą</button></form><div class="toolbar">${link('/meistrui/profilis','Pateikti profilį peržiūrai')}</div>`;}
  else if(part==='galerija'){title='Tavo vaizdai';content=`<p>Pasirink savo profilio portretą, darbų ir darbo aplinkos vaizdus.</p><form id="gallery-selection"><div class="gallery-grid">${[org.avatarImageId,...org.gallery].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).map(id=>`<label><span style="display:block">${photo(ctx,id)}</span><span class="check-label"><input type="checkbox" name="image" value="${id}" ${org.gallery.includes(id)?'checked':''}>${esc(ctx.media.get(id)?.alt)}</span></label>`).join('')}</div><button class="button accent" style="margin-top:24px">Išsaugoti galeriją</button></form><h2 style="font-size:26px;margin-top:36px">Vaizdo patikra</h2><form id="media-check" class="panel"><label for="media-file">PNG, JPEG arba WebP · iki 10 MB</label><input class="input" id="media-file" name="file" type="file" accept="image/png,image/jpeg,image/webp" required>${textarea('Kilmė ir teisės','rights','Mano vaizdas ir viešinimo teisė.','required')}<button class="button outline">Patikrinti formatą</button><p class="hint">Patikra parodo vaizdo matmenis ir tinkamą formatą.</p></form><div id="media-result">${ctx.state.uploads.map(u=>`<p>${esc(u.name)} · ${u.width} × ${u.height} · formatas patikrintas</p>`).join('')}</div>`;}
  else if(part==='pranesimai'){title='Pokalbiai';content=conversations(ctx,d,'professional')+`<details class="delivery-details"><summary>Vizitų pranešimų būsenos</summary>${list(d.outbox,o=>`<div class="list-row"><div><strong>${esc(o.type)}</strong>${badge(o.state)}</div>${btn('outbox-preview','Peržiūrėti',`data-id="${o.id}"`,'button outline small')}</div>`,'Po vizito patvirtinimo čia atsiras jo pranešimas.')}</details>`;}
  else if(part==='ataskaitos'){title='Vizitų suvestinė';const completed=d.bookings.filter(b=>b.status==='completed'),confirmed=d.bookings.filter(b=>b.status==='confirmed');content=`<p>Skaičiai apskaičiuoti iš pasirinktos organizacijos vizitų.</p><div class="table-wrap"><table><thead><tr><th>Būsena</th><th>Kiekis</th><th>Užregistruotų paslaugų vertė</th></tr></thead><tbody>${[['Atlikti',completed],['Patvirtinti',confirmed],['Atšaukti',d.bookings.filter(b=>b.status==='canceled')]].map(([l,rows])=>`<tr><td>${l}</td><td>${rows.length}</td><td>${money(rows.reduce((n,b)=>n+b.priceMinor,0))}</td></tr>`).join('')}</tbody></table></div><p class="hint">Paslaugų vertė nėra gauto apmokėjimo įrodymas. Mokėjimai platformoje neatliekami.</p>${btn('export-demo','Atsisiųsti savo vizitų CSV',`data-id="${org.id}"`,'button outline')}`;}
  else if(part==='integracijos'){title='Registracijos nuorodos ir integracijos';content=`<div class="panel"><h2 style="font-size:25px">Tavo profilio nuoroda</h2><p><a href="/${org.kind==='salon'?'salonai':'meistrai'}/${org.id}">${esc(location.origin)}/${org.kind==='salon'?'salonai':'meistrai'}/${org.id}</a></p>${btn('copy-profile','Kopijuoti nuorodą',`data-id="${org.id}"`,'button outline')}</div><h2 style="font-size:26px;margin-top:32px">Išorinė registracija</h2><p>Prijungimą suderink su platformos komanda. Peržiūrėsime tavo naudojamą registracijos sistemą ir jos duomenų perkėlimo galimybes.</p>${btn('integration-info','Kaip prijungiama sistema','','button outline')}<p class="hint">Prijungimas įsigalioja atskirai patvirtinus jo apimtį.</p>`;}
  else if(part==='nustatymai'){title='Registracijos taisyklės';content=`<div class="panel"><div class="summary-line"><span>Laiko zona</span><strong>Europe/Vilnius</strong></div><div class="summary-line"><span>Mažiausias išankstinis laikas</span><strong>30 min. </strong></div><div class="summary-line"><span>Laiko palaikymas</span><strong>2 min.</strong></div><div class="summary-line"><span>Viso vizito taisyklė</span><strong>Procedūra su priedais telpa kliento intervale</strong></div><p>Buferiai atskirai telpa resurso grafike. Pamainos redaktorius leidžia keisti darbo valandas.</p>${link('/meistrui/grafikas','Keisti grafiką','button outline')}</div><p style="margin-top:24px">Prisijungimo ir vizitų pranešimus gali valdyti savo paskyroje. <a href="/privatumas" class="link">Privatumas</a></p>`;}
  else return null;
  return shell(ctx,title,content,'professional');
}
function onboarding(ctx,d){const o=d.organizations[0],step=ctx.state.onboardingStep||0,v=ctx.state.onboarding;const names=['Veikla','Profilis ir vieta','Paslaugos','Grafikas','Medija ir būdas','Peržiūra'];let form='';
  if(step===0)form=select('Veiklos tipas','kind',[['solo','Solo meistras'],['salon','Salonas su komanda']],v.kind||o.kind)+field('Prekės ženklas / vardas','name',v.name||o.name,'text','required maxlength="100"');
  if(step===1)form=textarea('Veiklos aprašymas','bio',v.bio||o.bio,'required maxlength="600"')+select('Miestas','city',CITY_NAMES.map(c=>[c,c]),v.city||o.city)+`<p class="hint">Nurodyk savo veiklos vietą ir patikrink viešai rodomą informaciją.</p>`;
  if(step===2)form=`<p>${d.services.map(s=>esc(s.label)+' · '+money(s.priceMinor)+' · '+s.durationMin+' min.').join('<br>')}</p>${link('/meistrui/paslaugos','Atidaryti paslaugų redaktorių','link')}<label class="check-label"><input type="checkbox" name="servicesChecked" required ${v.servicesChecked?'checked':''}>Peržiūrėjau variantus ir priedus</label>`;
  if(step===3)form=`<p>${d.schedules.map(s=>hhmm(s.startMin)+'–'+hhmm(s.endMin)+' · pertrauka '+hhmm(s.breakStartMin)+'–'+hhmm(s.breakEndMin)).join('<br>')}</p>${link('/meistrui/grafikas','Redaguoti pamainą','link')}<label class="check-label"><input type="checkbox" name="scheduleChecked" required ${v.scheduleChecked?'checked':''}>Peržiūrėjau grafiko taisykles</label>`;
  if(step===4)form=`<h2 style="font-size:26px">Tavo darbai ir vieta</h2><p>Pridėk portretą, darbų ir darbo aplinkos vaizdus savo galerijoje. ${link('/meistrui/galerija','Atidaryti galeriją','link')}</p><p>Klientai rezervuoja pagal tavo paslaugų variantus ir darbo grafiką.</p><label class="check-label"><input type="checkbox" name="rightsChecked" required ${v.rightsChecked?'checked':''}>Turiu pateiktų vaizdų viešinimo teisę</label>`;
  if(step===5)form=`<h2 style="font-size:26px">${esc(v.name||o.name)}</h2><p>${esc(v.bio||o.bio)}</p><p>${esc(v.city||o.city)} · ${v.kind==='salon'?'Salonas':'Solo'}</p><p>Pateiktą versiją peržiūrės operatorius. Patvirtinus profilis pasirodys kataloge.</p>`;
  return shell(ctx,'Pradėk savo ritmu',`<nav class="booking-steps" aria-label="Pradžios etapai">${names.map((n,i)=>btn('onboarding-step',(i+1)+'. '+n,`data-id="${i}" ${i>step?'disabled':''}`,i===step?'button accent small':'button outline small')).join('')}</nav><form id="onboarding" class="panel prose">${form}<button class="button accent">${step===5?'Pateikti paraišką':'Tęsti'}</button></form>`,'professional');
}
async function operatorView(ctx,path,d){
  const part=path.split('/')[2]||'';let title='',content='';
  if(part===''){title='Profilių peržiūra';const rows=d.revisions.filter(r=>r.state==='pending');content=`<p>Peržiūrėk pateiktą profilio versiją ir grąžink patikslinti neaiškius duomenis.</p>${list(rows,r=>`<div class="list-row"><div><strong>${esc(r.name)}</strong><p>${esc(r.city||d.organizations.find(o=>o.id===r.organizationId)?.city||'')} · ${r.kind==='salon'?'Salonas':'Savarankiškas meistras'}</p>${badge(r.state)}</div>${btn('provider-review','Peržiūrėti versiją',`data-id="${r.id}"`,'button accent small')}</div>`,'Šiuo metu naujų versijų peržiūrai nėra.')}<h2 style="font-size:26px;margin-top:32px">Profilių būsenos</h2>${d.organizations.filter(o=>!o.approved).map(o=>`<div class="list-row"><div><strong>${esc(o.name)}</strong><p>${esc(status(o.profileState))}</p></div>${btn('operator-profile','Peržiūrėti būseną',`data-id="${o.id}"`,'button outline small')}</div>`).join('')||'<p>Peržiūros laukiančių profilių nėra.</p>'}`;}
  else if(part==='katalogas'){title='Katalogo tinkamumas';content=`<p>Pašalintas profilis neberodomas kataloge ir laisvų laikų paieškoje.</p><div class="table-wrap"><table class="eligibility-table"><thead><tr><th>Profilis</th><th>Miestas</th><th>Tinkamumas</th><th>Veiksmas</th></tr></thead><tbody>${d.organizations.map(o=>`<tr><td>${esc(o.name)}</td><td>${esc(o.city)}</td><td>${badge(o.approved?'approved':'draft')}</td><td>${btn('toggle-eligibility',o.approved?'Pašalinti iš katalogo':'Grąžinti į katalogą',`data-id="${o.id}"`,'button outline small')}</td></tr>`).join('')}</tbody></table></div><h2 style="font-size:26px;margin-top:32px">Paslaugų taksonomija</h2><div class="tabs">${d.taxonomy.map(t=>link('/paslaugos/'+t.id,t.label,'')).join('')}</div>`;}
  else if(part==='skundai'){title='Medijos ir atsiliepimų pranešimai';const pending=d.reviews.filter(r=>(r.state||(r.approved?'approved':'pending'))==='pending').slice().reverse();content=`<h2 style="font-size:26px">Atsiliepimai prieš viešinimą</h2><p>Viešinami tik peržiūrėti, su atliktu vizitu susieti atsiliepimai.</p>${ctx.adapter.mode==='real'?list(pending,r=>`<div class="list-row"><div><strong>${r.rating} / 5 · ${esc(d.organizations.find(o=>o.id===r.organizationId)?.name||'Profilis')}</strong><p>${esc(r.text)}</p>${badge('pending')}</div>${btn('review-moderation','Peržiūrėti atsiliepimą',`data-id="${r.id}"`,'button accent small')}</div>`,'Peržiūros laukiančių atsiliepimų nėra.'):''}<h2 style="font-size:26px;margin-top:32px">Pranešimai apie neatitikimus</h2><p>Pranešimus vertink pagal turinį, autorystę ir viešinimo teises.</p>${list(d.reports,r=>`<div class="list-row"><div><strong>${esc(r.target)}</strong><p>${esc(r.note)}</p>${badge(r.status)}</div>${btn('report-status','Peržiūrėti sprendimą',`data-id="${r.id}"`,'button outline small')}</div>`,'Pranešk neatitikimą profilio arba kontaktų puslapyje.')}`;}
  else if(part==='pristatymas'){title='Pristatymo diagnostika';content=`<p>Pristatymo būseną vertink atskirai nuo paties vizito įrašo.</p>${list(d.outbox,o=>`<div class="list-row"><div><strong>${esc(o.id)}</strong><p>${esc(o.organizationId)} · ${esc(o.bookingId)}</p>${badge(o.state)}</div>${btn('outbox-preview','Diagnostika',`data-id="${o.id}"`,'button outline small')}</div>`)}<h2 style="font-size:26px;margin-top:32px">Užklausos</h2>${d.inquiries.slice(0,10).map(i=>`<div class="list-row"><span>${esc(i.id)} · ${esc(i.organizationId)}</span>${badge(i.deliveryStatus)}</div>`).join('')}`;}
  else if(part==='turinys'){title='Gidai ir susiję puslapiai';content=`<p>Patvirtinti gidai ir jų veikiantys paslaugų ryšiai.</p>${list(guides,g=>`<div class="list-row"><div><strong>${esc(g.title)}</strong><p>${g.links.map(l=>link(l.href,l.label,'link')).join(' · ')}<br>Numatyta publikavimo data: ${date(g.dates.published)}</p><span class="pill">Patvirtinta versija</span></div>${link('/gidai/'+g.slug,'Peržiūrėti','button outline small')}</div>`,'Patvirtintų ir paskelbtų gidų dar nėra. Jų versijos valdomos turinio studijoje.',link('/redakcija','Peržiūrėti redakcinę tvarką','button outline'))}`;}
  else if(part==='rodikliai'){title='Madbeauty matavimas';const m=await ctx.adapter.metrics({scope:ctx.state.session});content=`<div class="table-wrap"><table><thead><tr><th>Rodiklis</th><th>Būsena</th></tr></thead><tbody><tr><td>Platformos įvykiai</td><td>${m.events??m.demoEvents}</td></tr><tr><td>Tikras srautas</td><td>Nematuota</td></tr><tr><td>Tikros tinkamos užklausos</td><td>Nematuota</td></tr><tr><td>Atlikti vizitai</td><td>Neįrodyta</td></tr></tbody></table></div><p style="margin-top:24px">Testinių duomenų rodikliai atskiriami nuo klientų paklausos.</p>`;}
  else return null;
  if(ctx.adapter.mode==='real'){if(part==='')content=offerQueue(ctx,d)+content;if(part==='katalogas')content+=taxonomyAdmin(ctx,d);}return shell(ctx,title,content,'operator');
}

const bookingById=(ctx,id)=>ctx.workspace.bookings.find(b=>b.id===id);
async function rescheduleDialog(ctx,b,selection=null){
  selection??={diena:String(Math.max(0,Math.min(30,Math.round((Date.parse(b.startAt)-Date.parse(ctx.dayInstant(0)))/86400000)))),nuo:'09:00',iki:'20:00'};
  ctx.dialogBooking=b;ctx.rescheduleSelection=selection;
  const a=await ctx.adapter.availability({providerServiceId:b.providerServiceId,addons:b.addonIds||[],practitionerId:b.practitionerId,dateKey:ctx.dayKey(selection.diena),dayOffset:Number(selection.diena),from:minute(selection.nuo),to:minute(selection.iki),ignoreBookingId:b.id,scope:ctx.state.session});
  a.slots.forEach(c=>ctx.candidates.set(c.id,c));
  ctx.openDialog('Pakeisti vizitą',`<p>Ankstesnis: ${date(b.startAt)} ${time(b.startAt)}–${time(b.endAt)} · ${money(b.priceMinor)}. Nepavykus pakeisti jis išlieka.</p><p>Pasirinkdamas naują laiką patvirtini prie jo nurodytą trukmę ir kainą pagal dabartinį paslaugos variantą.</p><form id="reschedule-filter">${select('Data','diena',Array.from({length:31},(_,i)=>[String(i),i===0?'Šiandien':ctx.dayLabel(i)]),selection.diena)}<div class="grid-2">${field('Nuo','nuo',selection.nuo,'time','required')}${field('Iki','iki',selection.iki,'time','required')}</div><button class="button outline">Rodyti naujus laikus</button></form><div class="divider"></div><div class="card-slots">${a.slots.map(c=>btn('confirm-reschedule',time(c.startAt)+'–'+time(c.endAt)+' · '+c.durationMin+' min. · '+money(c.priceMinor),`data-id="${esc(c.id)}"`,'slot')).join('')||`<p>${a.state==='stale'?'Kalendorius pasenęs.':'Tinkamų laikų nėra.'} Pakeisk intervalą.</p>`}</div>`);
}
function messageDialog(ctx,b){ctx.dialogBooking=b;const rows=ctx.workspace.messages.filter(m=>m.bookingId===b.id);ctx.openDialog('Pokalbis apie vizitą',`<p>${date(b.startAt)} · ${time(b.startAt)}. Pokalbis susietas su šiuo vizitu.</p>${rows.map(m=>`<div class="list-row"><div><strong>${esc(m.sender)} · ${time(m.createdAt)}</strong><p>${esc(m.text)}</p></div></div>`).join('')||'<p>Žinučių dar nėra.</p>'}<form id="message-form">${textarea('Žinutė','text','','required maxlength="600"')}<button class="button accent">Išsaugoti žinutę</button></form>`);}
export async function workspaceAction(ctx,action,button){
  if(await teamAccessAction(ctx,action,button)||await offerAdminAction(ctx,action,button)||await offerAction(ctx,action,button))return true;
  const id=button.dataset.id,d=ctx.workspace,scope=ctx.state.session;
  if(await calendarAction(ctx,action,button))return true;
  if(action==='sandbox-entry'&&ctx.adapter.mode==='demo'){const role=button.dataset.role;await ctx.selectRole(role,scope.organizationId||'demo-org-0',scope.clientId||'demo-client-0');return true;}
  if(action==='new-client'){ctx.openDialog('Pridėti klientą',`<p>Klientas galės prisijungti savo el. paštu. Kliento pridėjimas vizito nesukuria.</p><form id="new-client">${field('Kliento vardas','name','','text','required maxlength="80"')}${field('Kliento el. paštas','email','','email','required maxlength="254"')}<button class="button accent">Išsaugoti klientą</button></form>`);return true;}
  if(action==='new-staff'||action==='new-resource'){const staff=action==='new-staff';ctx.openDialog(staff?'Naujas komandos narys':'Nauja darbo vieta',`<form id="${action}">${field(staff?'Vardas ir pavardė':'Pavadinimas',staff?'name':'label','','text','required maxlength="100"')}<p class="hint">${staff?'Pridėjęs darbuotoją priskirk jam paslaugas ir patikrink darbo grafiką.':'Priskirk šią vietą paslaugoms, kurioms reikia bendro resurso.'}</p><button class="button accent">Pridėti</button></form>`);return true;}
  if(action==='complete-visit'){await ctx.adapter.completeBooking({scope,id,version:ctx.dialogBooking.version});ctx.closeDialog();ctx.toast('Vizitas pažymėtas atliktu.');await ctx.render();return true;}
  if(action==='new-service'){ctx.openDialog('Pridėti paslaugą',`<form id="new-service">${select('Kategorija','taxonomyServiceId',ctx.taxonomy.map(t=>[t.id,t.label]),'manikiuras')}${field('Paslaugos pavadinimas','label','','text','required maxlength="100"')}${field('Kaina (€)','price','25','number','required min="0" max="1000" step="0.01"')}${field('Trukmė (min.)','durationMin','60','number','required min="15" max="480" step="5"')}${field('Buferis prieš (min.)','bufferBeforeMin','5','number','required min="0" max="120"')}${field('Buferis po (min.)','bufferAfterMin','10','number','required min="0" max="120"')}${select('Meistras','practitionerId',d.practitioners.map(p=>[p.id,p.name]),d.practitioners[0].id)}${select('Darbo vieta','resourceId',d.resources.map(r=>[r.id,r.label]),d.resources[0].id)}<button class="button accent">Pridėti paslaugą</button></form>`);return true;}
  if(action==='visit-drawer'){const b=bookingById(ctx,id);ctx.dialogBooking=b;const service=d.services.find(s=>s.id===b.providerServiceId),client=d.clients.find(c=>c.id===b.clientId);ctx.openDialog('Vizito detalės',`<h3>${esc(b.serviceSnapshot?.label||service?.label||'Paslauga')}</h3><p>${esc(client?.name||'Klientas')}<br>${date(b.startAt)} · ${time(b.startAt)}–${time(b.endAt)}<br>${b.durationMin} min. · ${money(b.priceMinor)}</p><p>Meistras: ${esc(b.serviceSnapshot?.practitionerName||d.practitioners.find(p=>p.id===b.practitionerId)?.name||'Meistras')}<br>Darbo vieta: ${esc(d.resources.find(r=>r.id===b.resourceId)?.label||'Darbo vieta')}</p>${badge(b.status)}<div class="toolbar">${b.status==='confirmed'&&Date.parse(b.startAt)>Date.parse(ctx.adapter.clock.now)?btn('reschedule','Pakeisti laiką',`data-id="${b.id}"`,'button accent')+btn('cancel-visit','Atšaukti vizitą',`data-id="${b.id}"`,'button outline'):''}${b.status==='confirmed'&&Date.parse(b.endAt)<=Date.parse(ctx.adapter.clock.now)&&ctx.adapter.mode==='real'?btn('complete-visit','Pažymėti atliktu',`data-id="${b.id}"`,'button accent'):''}${btn('message-visit','Pokalbis',`data-id="${b.id}"`,'button outline')}</div>`);return true;}
  if(action==='reschedule'){await rescheduleDialog(ctx,bookingById(ctx,id));return true;}
  if(action==='confirm-reschedule'){await ctx.adapter.changeBooking({scope,id:ctx.dialogBooking.id,candidate:ctx.candidates.get(id),version:ctx.dialogBooking.version});ctx.closeDialog();ctx.toast('Vizito laikas pakeistas.');await ctx.render();return true;}
  if(action==='cancel-visit'){ctx.dialogBooking=bookingById(ctx,id);ctx.openDialog('Atšaukti vizitą',`<p>${date(ctx.dialogBooking.startAt)} · ${time(ctx.dialogBooking.startAt)}. Patvirtinus atšaukimą laikas bus atlaisvintas.</p><form id="cancel-visit">${textarea('Priežastis','reason','Pasikeitė mano planai.','required maxlength="300"')}<button class="button accent">Atšaukti šį vizitą</button></form>`);return true;}
  if(action==='review-visit'){ctx.dialogBooking=bookingById(ctx,id);ctx.openDialog('Atsiliepimas po vizito',`<p>Įvertink savo atliktą vizitą. Atsiliepimas peržiūrimas prieš viešinimą.</p><form id="review-form">${select('Įvertinimas','rating',[['5','5 / 5'],['4','4 / 5'],['3','3 / 5'],['2','2 / 5'],['1','1 / 5']],'5')}${textarea('Komentaras','text','','required maxlength="600"')}<button class="button accent">Išsaugoti atsiliepimą</button></form>`);return true;}
  if(action==='chat-select'){ctx.state.chatBookingId=id;ctx.saveUI();await ctx.render();return true;}
  if(action==='message-visit'){messageDialog(ctx,bookingById(ctx,id));return true;}
  if(action==='manual-visit'){if(!d.clients.length){ctx.openDialog('Pirmiausia pridėk klientą',`<p>Naujam vizitui reikalingas kliento vardas ir el. paštas.</p>${btn('new-client','Pridėti klientą','','button accent')}`);return true;}const services=d.services.filter(s=>s.active);if(!services.length){ctx.openDialog('Pirmiausia pridėk paslaugą',`<p>Naujam vizitui reikalinga paslauga su kaina ir trukme.</p>${link('/meistrui/paslaugos','Pridėti paslaugą','button accent')}`);return true;}ctx.manual=null;ctx.openDialog('Naujas vizitas',`<form id="manual-options">${select('Paslauga','serviceId',services.map(s=>[s.id,s.label+' · '+d.practitioners.find(p=>p.id===s.practitionerId).name]),services[0].id)}<div id="manual-service-summary" class="manual-service-summary" role="status">${manualServiceSummary(ctx,services[0].id)}</div>${select('Tavo klientas','clientId',d.clients.map(c=>[c.id,c.name]),d.clients[0]?.id)}${select('Data','diena',Array.from({length:31},(_,i)=>[String(i),i===0?'Šiandien':ctx.dayLabel(i)]),String(Math.max(0,Math.min(30,ctx.state.calendarDate?Math.round((Date.parse(ctx.state.calendarDate+'T12:00:00Z')-Date.parse(ctx.dayKey(0)+'T12:00:00Z'))/86400000):ctx.state.calendarDay||0))))}<button class="button accent">Patikrinti tinkamus laikus</button></form>`);return true;}
  if(action==='manual-confirm'){const c=ctx.candidates.get(id);await ctx.adapter.manualVisit({scope,candidate:c,clientId:ctx.manual.clientId,idempotencyKey:ctx.manual.key});ctx.closeDialog();ctx.toast('Vizitas pridėtas.');await ctx.render();return true;}
  if(action==='edit-service'){const s=d.services.find(s=>s.id===id);ctx.editing={table:'services',entity:s};serviceEditorDialog(ctx,s);return true;}
  if(action==='service-addon-add'||action==='service-addon-remove'){const values=serviceEditorValues(new FormData(document.querySelector('#service-editor')));if(action==='service-addon-add'){if(values.addons.length>=12)throw userError('Galima pridėti iki 12 priedų.');values.addons.push({id:'addon-'+crypto.randomUUID(),label:'',durationMin:15,priceMinor:0});}else values.addons.splice(Number(id),1);serviceEditorDialog(ctx,{...ctx.editing.entity,...values});return true;}
  if(action==='edit-schedule'){const s=d.schedules.find(s=>s.id===id);ctx.editing={table:'schedules',entity:s};ctx.openDialog('Pamaina ir uždarymas',`<form id="schedule-editor"><div class="grid-2">${field('Pamainos pradžia','start',hhmm(s.startMin),'time','required')}${field('Pamainos pabaiga','end',hhmm(s.endMin),'time','required')}</div><div class="grid-2">${field('Pertrauka nuo','breakStart',hhmm(s.breakStartMin),'time','required')}${field('Pertrauka iki','breakEnd',hhmm(s.breakEndMin),'time','required')}</div>${ctx.adapter.mode==='real'?field('Uždarymo data','closedDate',s.closedDate||'','date'):select('Uždarymo diena','closedDay',[['','Uždarymo nėra'],...Array.from({length:31},(_,i)=>[String(i),i===0?'Šiandien':ctx.dayLabel(i)])],s.closedDay===null?'':String(s.closedDay))}${ctx.adapter.mode==='real'?'<fieldset><legend>Darbo dienos</legend>'+[['Mon','Pirmadienis'],['Tue','Antradienis'],['Wed','Trečiadienis'],['Thu','Ketvirtadienis'],['Fri','Penktadienis'],['Sat','Šeštadienis'],['Sun','Sekmadienis']].map(([id,label])=>`<label class="check-label"><input type="checkbox" name="weekdays" value="${id}" ${(s.weekdays||[]).includes(id)?'checked':''}>${label}</label>`).join('')+'</fieldset>':''}<button class="button accent">Išsaugoti grafiką</button></form>`);return true;}
  if(action==='edit-resource'){const r=d.resources.find(r=>r.id===id);ctx.editing={table:'resources',entity:r};ctx.openDialog('Procedūros resursas',`<form id="resource-editor">${field('Resurso pavadinimas','label',r.label,'text','required')}<label class="check-label"><input name="active" type="checkbox" ${r.active?'checked':''}>Aktyvus laiko paieškoje</label><button class="button accent">Išsaugoti resursą</button></form>`);return true;}
  if(action==='edit-team'){const p=d.practitioners.find(p=>p.id===id);ctx.editing={table:'practitioners',entity:p};ctx.openDialog('Komandos narys',`<form id="team-editor">${field('Vardas','name',p.name,'text','required')}${select('Rolė','role',[['staff','Meistras'],['manager','Administratorius'],['owner','Savininkas']],p.role||'staff')}<p class="hint">Viešas komandos vaidmuo atskiras nuo paskyros prieigos.</p><button class="button accent">Išsaugoti</button></form>`);return true;}
  if(action==='inquiry-status'||action==='waitlist-status'){const table=action==='inquiry-status'?'inquiries':'waitlist',e=d[table].find(e=>e.id===id);ctx.editing={table,entity:e};ctx.openDialog(action==='inquiry-status'?'Užklausos būsena':'Laukiančiojo pasiūlymas',`<p><strong>${esc(d.clients.find(c=>c.id===e.clientId)?.name||'Klientas')}</strong><br>${esc(d.services.find(s=>s.id===e.providerServiceId)?.label||'Paslauga')}</p><p>${esc(e.note||'')}</p><form id="status-editor">${select('Būsena','value',table==='inquiries'?[['new','Nauja'],['qualified','Aptarta'],['closed','Užbaigta']]:[['waiting','Laukia'],['offered','Pasiūlyta'],['closed','Užbaigta']],table==='inquiries'?e.status:e.state)}<p class="hint">Įrašyta pasiūlymo būsena vizito nesukuria. Susisiek su klientu, aptark laiką ir paprašyk jo patvirtinti registraciją.</p><button class="button accent">Išsaugoti būseną</button></form>`);return true;}
  if(action==='onboarding-step'){ctx.state.onboardingStep=Number(id);await ctx.navigate(ctx.path,{replace:true});return true;}
  if(action==='provider-review'){await ctx.ensureMedia();const r=d.revisions.find(r=>r.id===id);ctx.reviewing=r;ctx.openDialog('Profilio versijos peržiūra',`<h3>${esc(r.name)}</h3><p>${esc(r.bio)}</p><p>${esc(r.city||d.organizations.find(o=>o.id===r.organizationId)?.city||'')} · ${r.kind==='salon'?'Salonas':'Savarankiškas meistras'}</p><div class="gallery-grid">${[r.avatarImageId,...(r.gallery||[])].filter(Boolean).map(id=>photo(ctx,id)).join('')}</div>${(d.media||[]).filter(a=>[r.avatarImageId,...(r.gallery||[])].includes(a.id)).map(a=>`<p class="hint"><strong>${esc(a.alt)}</strong><br>${esc(a.rights)}</p>`).join('')}<form id="moderation">${select('Sprendimas','state',[['approved','Patvirtinti profilį'],['returned','Grąžinti pataisymui']],'returned')}${textarea('Priežastis (privaloma grąžinant)','reason','Patikslinkite paslaugos apimtį ir medijos teises.','maxlength="500" data-required-if="state:returned"')}<button class="button accent">Išsaugoti sprendimą</button></form>`);return true;}
  if(action==='operator-profile'){const o=d.organizations.find(o=>o.id===id);ctx.openDialog('Profilio būsena',`<h3>${esc(o.name)}</h3><p>${esc(o.bio)}</p>${badge(o.profileState)}<p>Katalogo tinkamumą įvertink pagal pateiktą informaciją ir peržiūros rezultatą.</p>${btn('toggle-eligibility',o.approved?'Pašalinti iš katalogo':'Patvirtinti profilį',`data-id="${o.id}"`,'button accent')}`);return true;}
  if(action==='toggle-eligibility'){const o=d.organizations.find(o=>o.id===id);await ctx.adapter.edit({scope,table:'organizations',id,values:{approved:!o.approved,profileState:o.approved?'draft':'approved'},version:o.version});ctx.closeDialog();ctx.toast('Katalogo būsena atnaujinta.');await ctx.render();return true;}
  if(action==='review-moderation'){const r=d.reviews.find(r=>r.id===id);ctx.reviewingComment=r;ctx.openDialog('Atsiliepimo peržiūra',`<strong>${r.rating} / 5</strong><p>${esc(r.text)}</p><p class="hint">Atsiliepimas susietas su atliktu vizitu. Asmens kontaktai viešai nerodomi.</p><form id="review-moderation">${select('Sprendimas','state',[['approved','Viešinti'],['rejected','Neviešinti']],'rejected')}${textarea('Priežastis (privaloma neviešinant)','reason','','maxlength="500" data-required-if="state:rejected"')}<button class="button accent">Išsaugoti sprendimą</button></form>`);return true;}
  if(action==='report-status'){ctx.editing={table:'reports',entity:d.reports.find(r=>r.id===id)};ctx.openDialog('Pranešimo sprendimas',`<p>${esc(ctx.editing.entity.note)}</p><form id="status-editor">${select('Sprendimas','value',[['new','Naujas'],['resolved','Išspręstas'],['hidden','Paslėptas']],ctx.editing.entity.status)}<button class="button accent">Išsaugoti būseną</button></form>`);return true;}
  if(action==='outbox-preview'){const o=d.outbox.find(o=>o.id===id);ctx.openDialog('Pranešimo būsena',`<p><strong>${esc(o.id)}</strong><br>${esc(o.organizationId)}<br>${esc(o.bookingId)}<br>${esc(o.recipient)}</p>${badge(o.state)}<p>${o.state==='failed'?'Pranešimo pristatyti nepavyko. Vizitas išsaugotas.':'Pranešimas parengtas. Pristatymas gavėjui dar nepatvirtintas.'}</p>${btn('outbox-retry','Pakartoti parengimą',`data-id="${id}"`,'button outline')}`);return true;}
  if(action==='outbox-retry'){if(ctx.adapter.mode==='real')await ctx.adapter.retryOutbox({scope,id});else await ctx.adapter.edit({scope,table:'outbox',id,values:{state:'demo-only'}});ctx.closeDialog();ctx.toast('Pranešimo būsena atnaujinta.');await ctx.render();return true;}
  if(action==='message-template'){ctx.openDialog('Vizito pranešimo šablonas',`<p>Sveiki, {vardas}. Jūsų pasirinkimas: {paslauga}, {data}, {pradžia}–{pabaiga}. Peržiūrėti ar pakeisti galite vizito detalėse.</p><p>Šablonas peržiūrai. Jis nesiunčiamas ir nepriskiriamas rinkodarai.</p>`);return true;}
  if(action==='integration-info'){ctx.openDialog('Registracijos sistemos prijungimas',`<p>Prieš prijungiant tavo naudojamą registracijos sistemą suderiname profilio nuorodą, kuri sistema valdo laikus, laiko zoną ir atnaujinimo dažnį. Neprijungtas ar pasenęs kalendorius nerodo nepatikrintų laisvų laikų.</p><p>Prijungimo apimtis ir kaina aptariamos atskirai. Prieš pradėdami patikriname laikų atnaujinimą, persidengiančius vizitus ir pranešimų pristatymą.</p>`);return true;}
  if(action==='copy-profile'){const url=location.origin+'/'+(d.organizations[0].kind==='salon'?'salonai':'meistrai')+'/'+id;try{await navigator.clipboard.writeText(url);ctx.toast('profilio nuoroda nukopijuota.');}catch{ctx.openDialog('nuoroda',`<input class="input" aria-label="profilio nuoroda" value="${esc(url)}" readonly><p>Pažymėkite ir nukopijuokite nuorodą.</p>`);}return true;}
  if(action==='export-demo'){const rows=[['id','serviceId','startAt','endAt','status','priceMinor','isDemo'],...d.bookings.map(b=>[b.id,b.providerServiceId,b.startAt,b.endAt,b.status,b.priceMinor,ctx.adapter.mode!=='real'])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=id+'-vizitai.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ctx.toast('Eksportuota tik pasirinktos organizacijos vizitų suvestinė.');return true;}
  return false;
}
export async function workspaceForm(ctx,form,fd){
  if(await teamAccessForm(ctx,form,fd)||await offerAdminForm(ctx,form,fd)||await offerForm(ctx,form,fd))return true;
  const scope=ctx.state.session,d=ctx.workspace;
  if(await calendarForm(ctx,form,fd))return true;
  if(form.id==='new-client'){await ctx.adapter.createClient({organizationId:scope.organizationId,name:fd.get('name'),email:fd.get('email')});ctx.closeDialog();ctx.toast('Klientas įtrauktas į tavo sąrašą.');await ctx.navigate('/meistrui/klientai');return true;}
  if(form.id==='new-staff'||form.id==='new-resource'){await ctx.adapter[form.id==='new-staff'?'createStaff':'createResource']({...Object.fromEntries(fd),organizationId:scope.organizationId});ctx.closeDialog();ctx.toast('Įrašas pridėtas.');await ctx.render();return true;}
  if(form.id==='profile-upload'){const file=fd.get('file');if(!fd.has('rightsAccepted'))throw userError('Patvirtink vaizdo viešinimo teisę.');const a=await ctx.adapter.upload(file,{organizationId:scope.organizationId,usage:fd.get('usage'),alt:fd.get('alt'),rights:fd.get('rights')});ctx.media.set(a.id,a);ctx.toast('Vaizdas įkeltas. Pateik naują profilio versiją peržiūrai.');await ctx.render();return true;}
  if(form.id==='new-service'){const value=Object.fromEntries(fd);value.organizationId=scope.organizationId;value.priceMinor=Math.round(Number(value.price)*100);delete value.price;for(const k of ['durationMin','bufferBeforeMin','bufferAfterMin'])value[k]=Number(value[k]);await ctx.adapter.createService(value);ctx.closeDialog();ctx.toast('Paslauga pridėta.');await ctx.render();return true;}
  if(form.id==='role-entry'){const role=fd.get('role'),target=fd.get('target'),prefix={customer:'/paskyra',professional:'/meistrui',operator:'/operatorius'}[role];await ctx.selectRole(role,fd.get('organizationId'),fd.get('clientId'),target?.startsWith(prefix)?target:null);return true;}
  if(form.id==='switch-organization'){ctx.clearDrafts();ctx.state.session.organizationId=fd.get('organizationId');ctx.state.clientFilter='';ctx.state.booking=null;ctx.state.onboarding={};ctx.state.onboardingStep=0;ctx.state.calendarStaff='';ctx.state.chatBookingId=null;ctx.saveUI();await ctx.render();return true;}
  if(form.id==='client-filter'){ctx.state.clientFilter=fd.get('term');await ctx.render();return true;}
  if(form.id==='customer-profile'){await ctx.adapter.edit({scope,table:'clients',id:scope.clientId,values:{name:fd.get('name')}});ctx.toast('Vardas išsaugotas.');await ctx.render();return true;}
  if(form.id==='customer-settings'){await ctx.adapter.preferences({scope,service:fd.has('service'),marketing:fd.has('marketing')});ctx.toast('Pasirinkimai išsaugoti.');return true;}
  if(form.id==='cancel-visit'){await ctx.adapter.cancelBooking({scope,id:ctx.dialogBooking.id,version:ctx.dialogBooking.version,reason:fd.get('reason')});ctx.closeDialog();ctx.toast('Vizitas atšauktas.');await ctx.render();return true;}
  if(form.id==='reschedule-filter'){await rescheduleDialog(ctx,ctx.dialogBooking,Object.fromEntries(fd));return true;}
  if(form.id==='review-form'){await ctx.adapter.review({scope,bookingId:ctx.dialogBooking.id,rating:Number(fd.get('rating')),text:fd.get('text')});ctx.closeDialog();ctx.toast('Atsiliepimas pateiktas peržiūrai.');await ctx.render();return true;}
  if(form.id==='conversation-message'){await ctx.adapter.message({scope,bookingId:ctx.state.chatBookingId,text:fd.get('text')});await ctx.render();return true;}
  if(form.id==='message-form'){await ctx.adapter.message({scope,bookingId:ctx.dialogBooking.id,text:fd.get('text')});ctx.workspace=await ctx.adapter.workspace(scope);messageDialog(ctx,ctx.dialogBooking);return true;}
  if(form.id==='manual-options'){ctx.manual={serviceId:fd.get('serviceId'),clientId:fd.get('clientId'),key:'demo-manual-'+crypto.randomUUID()};const a=await ctx.adapter.availability({providerServiceId:ctx.manual.serviceId,practitionerId:d.practitionerId||undefined,scope,dateKey:ctx.dayKey(fd.get('diena')),dayOffset:Number(fd.get('diena')),from:540,to:1200});a.slots.forEach(c=>ctx.candidates.set(c.id,c));ctx.openDialog('Pasirink naujo vizito laiką',`<div class="manual-service-summary">${manualServiceSummary(ctx,ctx.manual.serviceId)}<p>${esc(d.clients.find(c=>c.id===ctx.manual.clientId)?.name||'Klientas')} · ${ctx.dayLabel(fd.get('diena'))}</p></div><p>Pasirinkus laiką vizitas bus išsaugotas. Patikrinta visa procedūra, pamaina ir resurso buferiai.</p><div class="card-slots">${a.slots.map(c=>btn('manual-confirm',time(c.startAt)+'–'+time(c.endAt),`data-id="${esc(c.id)}"`,'slot')).join('')||'<p>Tinkamų laikų nėra. Uždaryk panelę ir rinkis kitą dieną.</p>'}</div>`);return true;}
  if(['service-editor','schedule-editor','resource-editor','team-editor','status-editor'].includes(form.id)){
    const edit=ctx.editing;let values;
    if(form.id==='service-editor')values=serviceEditorValues(fd);
    if(form.id==='schedule-editor')values={...(ctx.adapter.mode==='real'?{weekdays:fd.getAll('weekdays'),closedDate:fd.get('closedDate')||null}:{}),startMin:minute(fd.get('start')),endMin:minute(fd.get('end')),breakStartMin:minute(fd.get('breakStart')),breakEndMin:minute(fd.get('breakEnd')),...(ctx.adapter.mode==='real'?{}:{closedDay:fd.get('closedDay')===''?null:Number(fd.get('closedDay'))})};
    if(form.id==='resource-editor')values={label:fd.get('label'),active:fd.has('active')};
    if(form.id==='team-editor')values={name:fd.get('name'),role:fd.get('role')};
    if(form.id==='status-editor')values={[edit.table==='waitlist'?'state':'status']:fd.get('value')};
    await ctx.adapter.edit({scope,table:edit.table,id:edit.entity.id,version:edit.entity.version,values});ctx.closeDialog();ctx.toast('Pakeitimas išsaugotas.');await ctx.render();return true;
  }
  if(form.id==='profile-revision'){await ctx.adapter.submitRevision({scope,name:fd.get('name'),bio:fd.get('bio'),kind:d.organizations[0].kind});ctx.toast('versija pateikta operatoriaus peržiūrai.');await ctx.render();return true;}
  if(form.id==='onboarding'){Object.assign(ctx.state.onboarding,Object.fromEntries(fd));if(ctx.state.onboardingStep===5){const v=ctx.state.onboarding;await ctx.adapter.submitRevision({scope,name:v.name||d.organizations[0].name,bio:v.bio||d.organizations[0].bio,kind:v.kind||d.organizations[0].kind,city:v.city||d.organizations[0].city});ctx.state.onboardingStep=0;ctx.toast('Profilis pateiktas peržiūrai.');await ctx.navigate('/meistrui/profilis');}else{ctx.state.onboardingStep++;await ctx.navigate(ctx.path,{replace:true});}ctx.saveUI();return true;}
  if(form.id==='gallery-selection'){const gallery=fd.getAll('image');if(gallery.length<1||gallery.length>6)throw userError('Pasirink nuo 1 iki 6 iliustracijų.');await ctx.adapter.edit({scope,table:'organizations',id:scope.organizationId,version:d.organizations[0].version,values:{gallery}});ctx.toast('galerija atnaujinta.');await ctx.render();return true;}
  if(form.id==='media-check'){const file=fd.get('file');if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)throw userError('Naudok PNG, JPEG arba WebP iki 10 MiB.');let bitmap;try{bitmap=await createImageBitmap(file);}catch{throw userError('Failo vaizdo nepavyko perskaityti.');}if(bitmap.width<200||bitmap.height<200){bitmap.close();throw userError('Vaizdas turi būti bent 200 × 200 px.');}const info={name:file.name,width:bitmap.width,height:bitmap.height,rights:fd.get('rights')};bitmap.close();ctx.state.uploads.push(info);ctx.saveUI();document.querySelector('#media-result').innerHTML=`<p role="status">${esc(info.name)} · ${info.width} × ${info.height} · failas patikrintas vietoje. Public importas neatliktas.</p>`;return true;}
  if(form.id==='review-moderation'){await ctx.adapter.moderateReview({id:ctx.reviewingComment.id,state:fd.get('state'),reason:fd.get('reason')});ctx.closeDialog();ctx.toast('Atsiliepimo peržiūros sprendimas išsaugotas.');await ctx.render();return true;}
  if(form.id==='moderation'){await ctx.adapter.moderate({scope,id:ctx.reviewing.id,state:fd.get('state'),reason:fd.get('reason')});ctx.closeDialog();ctx.toast('peržiūros sprendimas išsaugotas.');await ctx.render();return true;}
  return false;
}
